const items = $input.all();
return items.map(item => {
  const raw = item.json;

  const surfaceMaterial = String(raw['Surface Material'] || raw.surface_material || raw.surface || '').trim();
  const stainType = String(raw['Stain Type'] || raw.stain_type || raw.stain || '').trim();
  const technicianEmail = String(raw['Technician Email'] || raw.technician_email || raw.email || '').trim().toLowerCase();
  const technicianName = String(raw['Technician Name'] || raw.technician_name || raw.name || 'Field Technician').trim();
  const siteLocation = String(raw['Site Location'] || raw.site_location || raw.location || 'Not specified').trim();
  const surfaceAge = String(raw['Surface Age'] || raw.surface_age || 'Unknown').trim();
  const submissionTimestamp = raw['Timestamp'] || new Date().toISOString();
  const ticketId = raw['Ticket ID'] || `LG-${new Date().getFullYear()}-${String(Math.floor(Math.random()*900)+100)}`;

  const isEmailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(technicianEmail);
  const hasSurface = surfaceMaterial.length > 0;
  const hasStain = stainType.length > 0;
  const isValid = isEmailValid && hasSurface && hasStain;

  const systemPrompt = `You are a senior pressure-washing technician and chemical safety expert at Lichen & Grime, a specialized exterior cleaning startup. Field technicians submit a surface + stain combination and you provide a precise, safe cleaning recommendation that prevents property damage and protects the worker.

Return ONLY valid JSON in this exact format:
{
  "chemicalAgent": "<specific chemical name>",
  "concentration": "<dilution ratio or percentage>",
  "psiMin": <number>,
  "psiMax": <number>,
  "nozzleAngle": "<degrees, e.g. 25 or 40>",
  "dwellTimeMinutes": <number>,
  "ppeRequired": ["<list>", "<of>", "<items>"],
  "surfaceCategory": "<one of: Soft Wash, Standard, Heavy Duty>",
  "warnings": ["<critical safety warnings>"],
  "procedureSteps": ["<step 1>", "<step 2>", "<step 3>"]
}

Safety rules:
- Wood (cedar, redwood, teak): SOFT WASH ONLY (≤500 PSI) with surfactant + low-pressure rinse
- Painted/stained surfaces: ≤1500 PSI, 40° nozzle
- Limestone/sandstone/travertine: SOFT WASH (≤500 PSI) — acidic chemicals corrode
- Concrete/pavers: 2500-3500 PSI OK with degreaser
- Vinyl/aluminum siding: 1500-2000 PSI with 25° nozzle
- Composite deck: ≤1500 PSI, oxygen bleach (no chlorine)
- Asphalt shingles: SOFT WASH ONLY — never high pressure

Chemical guidance:
- Mold/algae/lichen: Sodium Hypochlorite 0.5-3% + surfactant
- Oil/grease: Alkaline degreaser (pH 11-13)
- Rust/iron staining: Oxalic Acid 5-10%
- Efflorescence: Phosphoric or Muriatic Acid (DILUTED — wear PPE)
- Hard water: Vinegar or CLR-type acid cleaner
- UV-grayed wood: Oxalic Acid + Sodium Percarbonate brightener

Dwell time: 5-15 min typical. Never let chemicals dry on surface.

PPE: Always include nitrile gloves + chemical splash goggles. Add face shield + apron for acids. Add respirator for confined spaces.

Warnings: Always flag plant/landscaping protection, neighbor property risk, runoff containment, and cure-time before re-rinse.`;

  const userMessage = `Surface Material: ${surfaceMaterial}\nStain Type: ${stainType}\nSurface Age: ${surfaceAge}\nSite Location: ${siteLocation}\n\nProvide a complete safety-first cleaning recommendation as structured JSON.`;

  return { json: {
    ticketId,
    submissionTimestamp,
    technicianName,
    technicianEmail,
    surfaceMaterial,
    stainType,
    surfaceAge,
    siteLocation,
    isValid,
    systemPrompt,
    userMessage,
    rawRow: raw
  }};
});

const items = $input.all();
return items.map(item => {
  const aiRaw = item.json;
  const responseContent = aiRaw.choices?.[0]?.message?.content || '';

  let parsed = {
    chemicalAgent: 'Unknown',
    concentration: 'See manual',
    psiMin: 500,
    psiMax: 1500,
    nozzleAngle: '40',
    dwellTimeMinutes: 10,
    ppeRequired: ['Nitrile gloves', 'Chemical splash goggles'],
    surfaceCategory: 'Standard',
    warnings: ['Verify chemical compatibility before application'],
    procedureSteps: ['Test in inconspicuous area', 'Apply chemical', 'Rinse thoroughly']
  };

  try {
    const cleaned = responseContent.trim()
      .replace(/^```json?\n?/, '')
      .replace(/\n?```$/, '')
      .trim();
    const aiOutput = JSON.parse(cleaned);
    parsed = { ...parsed, ...aiOutput };
  } catch (e) {
    const chemMatch = responseContent.match(/"chemicalAgent"\s*:\s*"([^"]+)"/);
    if (chemMatch) parsed.chemicalAgent = chemMatch[1];
    const concMatch = responseContent.match(/"concentration"\s*:\s*"([^"]+)"/);
    if (concMatch) parsed.concentration = concMatch[1];
    const psiMinMatch = responseContent.match(/"psiMin"\s*:\s*(\d+)/);
    if (psiMinMatch) parsed.psiMin = parseInt(psiMinMatch[1]);
    const psiMaxMatch = responseContent.match(/"psiMax"\s*:\s*(\d+)/);
    if (psiMaxMatch) parsed.psiMax = parseInt(psiMaxMatch[1]);
  }

  const psiRange = `${parsed.psiMin}-${parsed.psiMax} PSI`;
  const ppeListText = (parsed.ppeRequired || []).map(p => '• ' + p).join('<br/>');
  const warningsText = (parsed.warnings || []).map(w => '⚠️ ' + w).join('<br/>');
  const stepsText = (parsed.procedureSteps || []).map((s, i) => (i+1) + '. ' + s).join('<br/>');

  const categoryColor = parsed.surfaceCategory === 'Soft Wash' ? 3066993
    : parsed.surfaceCategory === 'Heavy Duty' ? 15158332
    : 16776960;

  const prevData = $('Parse Form & Build AI Prompt').item.json;

  return { json: {
    ...prevData,
    chemicalAgent: parsed.chemicalAgent,
    concentration: parsed.concentration,
    psiMin: parsed.psiMin,
    psiMax: parsed.psiMax,
    psiRange,
    nozzleAngle: parsed.nozzleAngle,
    dwellTimeMinutes: parsed.dwellTimeMinutes,
    ppeRequired: parsed.ppeRequired,
    ppeListText,
    surfaceCategory: parsed.surfaceCategory,
    categoryColor,
    warnings: parsed.warnings,
    warningsText,
    procedureSteps: parsed.procedureSteps,
    stepsText,
    aiRawResponse: responseContent,
    processedAt: new Date().toISOString()
  }};
});

const items = $input.all();
return items.map(item => {
  const err = item.json;
  const now = new Date().toISOString();
  const errorId = `ERR-${now.slice(0,10).replace(/-/g,'')}-${Math.floor(Math.random()*9000)+1000}`;
  return { json: {
    errorId,
    timestamp: now,
    ticketId: err.ticketId || 'UNKNOWN',
    technicianEmail: err.technicianEmail || 'unknown',
    surfaceMaterial: err.surfaceMaterial || 'unknown',
    failedNode: err.node?.name || err.execution?.lastNodeExecuted || 'Unknown Node',
    errorType: err.name || 'WorkflowError',
    errorMessage: err.message || 'No message available',
    workflowName: 'Lichen & Grime — PSI Assistant'
  }};
});
